#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <thread>

std::queue<int> cola;                         // estado compartido
std::mutex m;                                 // protege a cola y a terminado
std::condition_variable cv;                   // "la campanita"
bool terminado = false;

void productor() {
    for (int i = 1; i <= 5; i++) {
        {
            std::lock_guard<std::mutex> lk(m); // protege el push
            cola.push(i);
        }                                      // suelta m ANTES de avisar
        cv.notify_one();                       // despierta a un consumidor dormido
    }
    {
        std::lock_guard<std::mutex> lk(m);
        terminado = true;                      // también se modifica bajo el mutex
    }
    cv.notify_all();                           // avisa a todos que ya no habrá más
}

void consumidor() {
    while (true) {
        std::unique_lock<std::mutex> lk(m);    // unique_lock: wait necesita soltarlo
        // Duerme MIENTRAS la cola esté vacía y no hayamos terminado.
        cv.wait(lk, [] { return !cola.empty() || terminado; });
        if (cola.empty()) break;               // terminado y sin datos: salimos
        int x = cola.front();
        cola.pop();
        lk.unlock();                           // procesar fuera de la sección crítica
        std::cout << "consumí " << x << '\n';
    }
}

int main() {
    std::thread p(productor), c(consumidor);
    p.join();
    c.join();
}

